import type { VercelRequest, VercelResponse } from '@vercel/node'
import { serviceClient, requireSession } from './_lib/sessionAuth.js'
import {
  AGENT_REFERRAL_EMAILS,
  agentReferralLink,
  agentReferralSms,
  ensureAllAgentReferrals,
  referralDirectoryEmailText,
} from './_lib/agentReferrals.js'
import { logDelivery, sendEmailDirect, sendSmsAfrosoft, type Delivery } from './_lib/notify.js'
import { auditLog } from './_lib/audit.js'

/**
 * Backfills/distributes persistent field-agent referral links.
 *
 * The links themselves are generated by migrations + ensureAllAgentReferrals;
 * this endpoint is the controlled Super Admin action that sends the complete
 * register to the company mailboxes and, by default, texts each active agent
 * their own link. Notification failures are returned as warnings — they never
 * roll back the referral-code backfill.
 */
export default async function handler(req: VercelRequest, res: VercelResponse) {
  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' })

  const admin = serviceClient()
  if (!admin) return res.status(500).json({ error: 'Server is not configured.' })
  const session = await requireSession(req, admin)
  if (!session) return res.status(401).json({ error: 'Sign-in required.' })

  const { data: caller } = await admin.from('profiles')
    .select('role')
    .eq('id', session.user.id)
    .maybeSingle()
  if (caller?.role !== 'super_admin') {
    return res.status(403).json({ error: 'Only a Super Admin can distribute the field-agent referral register.' })
  }

  const body = (typeof req.body === 'string' ? JSON.parse(req.body || '{}') : (req.body ?? {})) as {
    action?: 'backfill' | 'distribute'
    notifyAgents?: boolean
  }
  if (body.action && !['backfill', 'distribute'].includes(body.action)) {
    return res.status(400).json({ error: 'action must be backfill or distribute.' })
  }

  const ensured = await ensureAllAgentReferrals(admin)
  if (ensured.error || !ensured.data) {
    return res.status(500).json({ error: ensured.error ?? 'Could not prepare agent referral links.' })
  }
  const agents = ensured.data
  const missing = agents.filter(a => !a.referralCode)
  if (missing.length) {
    return res.status(500).json({ error: `Could not issue referral links for ${missing.map(a => a.name).join(', ')}.` })
  }

  if (body.action !== 'distribute') {
    return res.status(200).json({ ok: true, agents: agents.map(a => ({ ...a, referralLink: agentReferralLink(a.referralCode) })) })
  }

  const deliveries: Delivery[] = []
  const email = await sendEmailDirect(
    AGENT_REFERRAL_EMAILS.join(', '),
    'Field-agent referral link register',
    referralDirectoryEmailText(agents),
  )
  deliveries.push(email)
  await logDelivery(admin, 'system', 'agent_referral_directory', email)

  if (body.notifyAgents !== false) {
    for (const agent of agents.filter(a => a.active && a.phone)) {
      const delivery = await sendSmsAfrosoft(agent.phone!, agentReferralSms(agent))
      deliveries.push(delivery)
      await logDelivery(admin, 'system', agent.referralCode, delivery)
    }
  }

  await auditLog({
    operatorId: session.user.id,
    entityType: 'system',
    entityId: 'agent_referrals',
    action: 'agent_referral_register_distributed',
    changes: {
      agents: { old: null, new: agents.length },
      companyRecipients: { old: null, new: [...AGENT_REFERRAL_EMAILS] },
      agentSms: { old: null, new: body.notifyAgents !== false },
    },
    source: 'web',
  })

  const failed = deliveries.filter(d => d.status !== 'sent')
  return res.status(200).json({
    ok: failed.length === 0,
    agents: agents.map(a => ({ ...a, referralLink: agentReferralLink(a.referralCode) })),
    deliveries,
    warnings: failed.map(d => `${d.channel} → ${d.recipient}: ${d.detail ?? 'failed'}`),
  })
}
